@using sv_a0beb22291824677b0b38f9d5f7ee29a.Services

<span class="badge" style="background-color: @(Theme?.AccentColor ?? "#0d6efd")">
    @(Theme?.Theme.ToString() ?? "Light")
</span>

@code {
    [CascadingParameter]
    private ThemeInfo? Theme { get; set; }
}

@using sv_a0beb22291824677b0b38f9d5f7ee29a.Services
@rendermode InteractiveServer
@inject ThemeService ThemeService

<div class="nav-item px-3">
    <button class="btn btn-sm btn-outline-light w-100" @onclick="ToggleTheme">
        @(_isDark ? "☀️ Light" : "🌙 Dark")
    </button>
</div>

@code {
    [CascadingParameter]
    private ThemeInfo? Theme { get; set; }

    private bool _isDark;

    protected override void OnParametersSet()
    {
        _isDark = Theme?.Theme == Theme.Dark;
    }

    private async Task ToggleTheme()
    {
        var next = _isDark ? Services.Theme.Light : Services.Theme.Dark;
        await ThemeService.SetThemeAsync(next);
    }
}

@page "/settings"
@rendermode InteractiveServer
@using sv_a0beb22291824677b0b38f9d5f7ee29a.Services
@inject ThemeService ThemeService

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="mb-3">
    <label class="form-label">Theme</label>
    <select class="form-select" style="max-width:200px"
            value="@_selectedTheme"
            @onchange="OnThemeChanged">
        @foreach (var t in Enum.GetValues<Theme>())
        {
            <option value="@t">@t</option>
        }
    </select>
</div>

<div class="mb-3">
    <label class="form-label">Accent Color</label>
    <input type="color" class="form-control form-control-color"
           value="@_accentColor"
           @onchange="OnAccentChanged" />
</div>

<p>
    Current:
    <span class="badge" style="background-color: @_accentColor">
        @_selectedTheme
    </span>
</p>

@code {
    [CascadingParameter]
    private ThemeInfo? Theme { get; set; }

    private Theme _selectedTheme;
    private string _accentColor = "#0d6efd";

    protected override void OnParametersSet()
    {
        if (Theme is not null)
        {
            _selectedTheme = Theme.Theme;
            _accentColor = Theme.AccentColor;
        }
    }

    private async Task OnThemeChanged(ChangeEventArgs e)
    {
        if (Enum.TryParse<Theme>(e.Value?.ToString(), out var parsed))
        {
            _selectedTheme = parsed;
            await ThemeService.UpdateAsync(_selectedTheme, _accentColor);
        }
    }

    private async Task OnAccentChanged(ChangeEventArgs e)
    {
        _accentColor = e.Value?.ToString() ?? _accentColor;
        await ThemeService.UpdateAsync(_selectedTheme, _accentColor);
    }
}

